use vstd::prelude::*;

verus! {

fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
    requires
        // the array is non‐empty
        list.len() > 0,
        // n is a strict interior index
        n < list.len(),
        n > 0,
    ensures
        // the result has the same length
        new_list.len() == list.len(),
    ensures
        // first part is list[n..]
        forall|k: usize| k < list.len() - n ==> new_list[k] == list[n + k],
    ensures
        // second part is list[..n]
        forall|k: usize| k < n ==> new_list[list.len() - n + k] == list[k],
{
    let len = list.len();

    // build the first segment: list[n..len]
    let mut new_list: Vec<i32> = Vec::new();
    let mut i: usize = n;
    while i < len
        invariant
            // i marches from n up to len
            n <= i <= len,
            // we've pushed exactly i - n elements so far
            new_list.len() == i - n,
            // and they agree with list[n..i]
            forall|k: usize| k < new_list.len() ==>
                new_list[k] == list[n + k],
        decreases
            len - i,
    {
        new_list.push(list[i]);
        i += 1;
    }

    // build the second segment: list[0..n]
    let mut j: usize = 0;
    while j < n
        invariant
            // j marches from 0 up to n
            j <= n,
            // total elements so far is (len - n) + j
            new_list.len() == (len - n) + j,
            // first segment remains correct
            forall|k: usize| k < len - n ==>
                new_list[k] == list[n + k],
            // and we have correctly appended list[0..j]
            forall|k: usize| k < j ==>
                new_list[len - n + k] == list[k],
        decreases
            n - j,
    {
        new_list.push(list[j]);
        j += 1;
    }

    new_list
}

} // end verus!

